const _library = async function library(FileAttachment){
  const blob = await new Response(
    (await FileAttachment("index.cjs").stream())
      .pipeThrough(new DecompressionStream("gzip"))
  ).blob();
  const text = await blob.text();
  const module = {exports: {}};
  const exports = module.exports;
  new Function("module", "exports", text)(module, exports);
  return module.exports;
};

const _slugify = function slugify(library){return(
  library.slugify
)};

const _VERSION = function VERSION(library){return(
  library.VERSION
)};

const _slugs = function slugs(slugify){return(
  ["Hello World", "  A/B  test "].map(slugify)
)};

export default function define(runtime, observer) {
  const main = runtime.module();
  const $def = (pid, name, deps, fn) => {
    main.variable(observer(name)).define(name, deps, fn).pid = pid;
  };

  const fileAttachments = new Map(["index.cjs"].map((name) => {
    const module_name = "@tomlarkworthy/slugger";
    const {status, mime, bytes} = window.lopecode.contentSync(module_name + "/" + encodeURIComponent(name));
    const blob_url = URL.createObjectURL(new Blob([bytes], { type: mime}));
    return [name, {url: blob_url, mimeType: mime}];
  }));
  main.builtin("FileAttachment", runtime.fileAttachments(name => fileAttachments.get(name)));

  $def("_intro", "intro", ["md"], _intro);
  $def("_library", "library", ["FileAttachment"], _library);
  $def("_slugify", "slugify", ["library"], _slugify);
  $def("_VERSION", "VERSION", ["library"], _VERSION);
  $def("_slugs", "slugs", ["slugify"], _slugs);
  return main;
}

